// Cert Lab - what the packages put on disk: unit files and the default configuration files, written to match
// the layout and the defaults of RHEL 9 (shortened where the real files are long, keeping the lines that matter).
using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Text;

namespace CertLab
{
    public static partial class Packages
    {
        public static string UnitText(string unit)
        {
            switch (unit)
            {
                case "sshd.service": return "[Unit]\nDescription=OpenSSH server daemon\nDocumentation=man:sshd(8) man:sshd_config(5)\nAfter=network.target sshd-keygen.target\nWants=sshd-keygen.target\n\n[Service]\nType=notify\nEnvironmentFile=-/etc/sysconfig/sshd\nExecStart=/usr/sbin/sshd -D $OPTIONS\nExecReload=/bin/kill -HUP $MAINPID\nKillMode=process\nRestart=on-failure\nRestartSec=42s\n\n[Install]\nWantedBy=multi-user.target\n";
                case "httpd.service": return "[Unit]\nDescription=The Apache HTTP Server\nWants=httpd-init.service\nAfter=network.target remote-fs.target nss-lookup.target httpd-init.service\nDocumentation=man:httpd.service(8)\n\n[Service]\nType=notify\nEnvironment=LANG=C\n\nExecStart=/usr/sbin/httpd $OPTIONS -DFOREGROUND\nExecReload=/usr/sbin/httpd $OPTIONS -k graceful\n# Send SIGWINCH for graceful stop\nKillSignal=SIGWINCH\nKillMode=mixed\nPrivateTmp=true\nOOMPolicy=continue\n\n[Install]\nWantedBy=multi-user.target\n";
                case "chronyd.service": return "[Unit]\nDescription=NTP client/server\nDocumentation=man:chronyd(8) man:chrony.conf(5)\nAfter=chronyd-restricted.service ntpdate.service sntp.service ntpd.service\nConflicts=ntpd.service systemd-timesyncd.service\nConditionCapability=CAP_SYS_TIME\n\n[Service]\nType=forking\nPIDFile=/run/chrony/chronyd.pid\nEnvironmentFile=-/etc/sysconfig/chronyd\nExecStart=/usr/sbin/chronyd $OPTIONS\n\n[Install]\nWantedBy=multi-user.target\n";
                case "crond.service": return "[Unit]\nDescription=Command Scheduler\nAfter=auditd.service nss-user-lookup.target systemd-user-sessions.service time-sync.target ypbind.service autofs.service\n\n[Service]\nEnvironmentFile=/etc/sysconfig/crond\nExecStart=/usr/sbin/crond -n $CRONDARGS\nExecReload=/bin/kill -URG $MAINPID\nKillMode=process\nRestart=on-failure\nRestartSec=30s\n\n[Install]\nWantedBy=multi-user.target\n";
                case "atd.service": return "[Unit]\nDescription=Deferred execution scheduler\nDocumentation=man:atd(8)\nAfter=syslog.target systemd-user-sessions.service\n\n[Service]\nEnvironmentFile=/etc/sysconfig/atd\nExecStart=/usr/sbin/atd -f $OPTS\nIgnoreSIGPIPE=no\n\n[Install]\nWantedBy=multi-user.target\n";
                case "rsyslog.service": return "[Unit]\nDescription=System Logging Service\nWants=network.target network-online.target\nAfter=network.target network-online.target\nDocumentation=man:rsyslogd(8)\nDocumentation=https://www.rsyslog.com/doc/\n\n[Service]\nType=notify\nEnvironmentFile=-/etc/sysconfig/rsyslog\nExecStart=/usr/sbin/rsyslogd -n $SYSLOGD_OPTIONS\nExecReload=/usr/bin/kill -HUP $MAINPID\nUMask=0066\nStandardOutput=null\nRestart=on-failure\n\n[Install]\nWantedBy=multi-user.target\n";
                case "firewalld.service": return "[Unit]\nDescription=firewalld - dynamic firewall daemon\nBefore=network-pre.target\nWants=network-pre.target\nAfter=dbus.service\nAfter=polkit.service\nConflicts=iptables.service ip6tables.service ebtables.service ipset.service nftables.service\nDocumentation=man:firewalld(1)\n\n[Service]\nEnvironmentFile=-/etc/sysconfig/firewalld\nExecStart=/usr/sbin/firewalld --nofork --nopid $FIREWALLD_ARGS\nExecReload=/bin/kill -HUP $MAINPID\nStandardOutput=null\nStandardError=null\nType=dbus\nBusName=org.fedoraproject.FirewallD1\nKillMode=mixed\n\n[Install]\nWantedBy=multi-user.target\nAlias=dbus-org.fedoraproject.FirewallD1.service\n";
                case "NetworkManager.service": return "[Unit]\nDescription=Network Manager\nDocumentation=man:NetworkManager(8)\nWants=network.target\nAfter=network-pre.target dbus.service\nBefore=network.target network.service\n\n[Service]\nType=dbus\nBusName=org.freedesktop.NetworkManager\nExecReload=/usr/bin/busctl call org.freedesktop.NetworkManager /org/freedesktop/NetworkManager org.freedesktop.NetworkManager Reload u 0\nExecStart=/usr/sbin/NetworkManager --no-daemon\nRestart=on-failure\n\n[Install]\nWantedBy=multi-user.target\nAlso=NetworkManager-dispatcher.service\n";
                case "tuned.service": return "[Unit]\nDescription=Dynamic System Tuning Daemon\nAfter=systemd-sysctl.service network.target dbus.service polkit.service\nRequires=dbus.service\nConflicts=cpupower.service auto-cpufreq.service tlp.service power-profiles-daemon.service\nDocumentation=man:tuned(8) man:tuned.conf(5) man:tuned-adm(8)\n\n[Service]\nType=dbus\nPIDFile=/run/tuned/tuned.pid\nBusName=com.redhat.tuned\nExecStart=/usr/sbin/tuned -l -P\n\n[Install]\nWantedBy=multi-user.target\n";
                case "auditd.service": return "[Unit]\nDescription=Security Auditing Service\nDefaultDependencies=no\nAfter=local-fs.target systemd-tmpfiles-setup.service\nConflicts=shutdown.target\nBefore=sysinit.target shutdown.target\nDocumentation=man:auditd(8) https://github.com/linux-audit/audit-documentation\n\n[Service]\nType=forking\nPIDFile=/run/auditd.pid\nExecStart=/sbin/auditd\nRestart=on-failure\nRefuseManualStop=yes\n\n[Install]\nWantedBy=multi-user.target\n";
                case "autofs.service": return "[Unit]\nDescription=Automounts filesystems on demand\nAfter=network.target ypbind.service sssd.service network-online.target remote-fs.target rpc-statd.service rpcbind.service\nWants=network-online.target rpc-statd.service rpcbind.service\n\n[Service]\nType=forking\nPIDFile=/run/autofs.pid\nEnvironmentFile=-/etc/sysconfig/autofs\nExecStart=/usr/sbin/automount $OPTIONS --pid-file /run/autofs.pid\nExecReload=/usr/bin/kill -HUP $MAINPID\nTimeoutSec=180\n\n[Install]\nWantedBy=multi-user.target\n";
                case "nfs-server.service": return "[Unit]\nDescription=NFS server and services\nDefaultDependencies=no\nRequires=network.target proc-fs-nfsd.mount\nAfter=network.target proc-fs-nfsd.mount rpcbind.socket nfs-mountd.service\n\n[Service]\nType=oneshot\nRemainAfterExit=yes\nExecStart=/usr/sbin/rpc.nfsd\nExecStop=/usr/sbin/rpc.nfsd 0\n\n[Install]\nWantedBy=multi-user.target\n";
                case "cockpit.socket": return "[Unit]\nDescription=Cockpit Web Service Socket\nDocumentation=man:cockpit-ws(8)\nWants=cockpit-motd.service\n\n[Socket]\nListenStream=9090\nExecStartPost=-/usr/share/cockpit/issue/update-issue '' localhost\nExecStopPost=-/bin/ln -snf active.issue /run/cockpit/issue\n\n[Install]\nWantedBy=sockets.target\n";
                case "logrotate.timer": return "[Unit]\nDescription=Daily rotation of log files\nDocumentation=man:logrotate(8) man:logrotate.conf(5)\n\n[Timer]\nOnCalendar=daily\nAccuracySec=1h\nPersistent=true\n\n[Install]\nWantedBy=timers.target\n";
                case "nginx.service": return "[Unit]\nDescription=The nginx HTTP and reverse proxy server\nAfter=network-online.target remote-fs.target nss-lookup.target\nWants=network-online.target\n\n[Service]\nType=forking\nPIDFile=/run/nginx.pid\nExecStartPre=/usr/bin/rm -f /run/nginx.pid\nExecStartPre=/usr/sbin/nginx -t\nExecStart=/usr/sbin/nginx\nExecReload=/usr/sbin/nginx -s reload\nKillSignal=SIGQUIT\nTimeoutStopSec=5\nKillMode=mixed\nPrivateTmp=true\n\n[Install]\nWantedBy=multi-user.target\n";
                case "vsftpd.service": return "[Unit]\nDescription=Vsftpd ftp daemon\nAfter=network.target\n\n[Service]\nType=forking\nExecStart=/usr/sbin/vsftpd /etc/vsftpd/vsftpd.conf\n\n[Install]\nWantedBy=multi-user.target\n";
                case "mariadb.service": return "[Unit]\nDescription=MariaDB 10.5 database server\nDocumentation=man:mariadbd(8)\nAfter=network.target\n\n[Service]\nType=notify\nUser=mysql\nGroup=mysql\nExecStart=/usr/libexec/mariadbd --basedir=/usr $MYSQLD_OPTS $_WSREP_NEW_CLUSTER\n\n[Install]\nWantedBy=multi-user.target\nAlias=mysql.service\nAlias=mysqld.service\n";
                case "systemd-journald.service": return "[Unit]\nDescription=Journal Service\nDocumentation=man:systemd-journald.service(8) man:journald.conf(5)\nDefaultDependencies=no\nRequires=systemd-journald.socket\nAfter=systemd-journald.socket systemd-journald-dev-log.socket systemd-journald-audit.socket syslog.socket\nBefore=sysinit.target\n\n[Service]\nDeviceAllow=char-* rw\nExecStart=/usr/lib/systemd/systemd-journald\nRestart=always\nType=notify\n";
                case "systemd-logind.service": return "[Unit]\nDescription=User Login Management\nDocumentation=man:sd-login(3)\nDocumentation=man:systemd-logind.service(8)\nAfter=nss-user-lookup.target user.slice modprobe@drm.service\n\n[Service]\nBusName=org.freedesktop.login1\nExecStart=/usr/lib/systemd/systemd-logind\nRestart=always\nType=notify\n";
                case "multi-user.target": return "[Unit]\nDescription=Multi-User System\nDocumentation=man:systemd.special(7)\nRequires=basic.target\nConflicts=rescue.service rescue.target\nAfter=basic.target rescue.service rescue.target\nAllowIsolate=yes\n";
                case "graphical.target": return "[Unit]\nDescription=Graphical Interface\nDocumentation=man:systemd.special(7)\nRequires=multi-user.target\nWants=display-manager.service\nConflicts=rescue.service rescue.target\nAfter=multi-user.target rescue.service rescue.target display-manager.service\nAllowIsolate=yes\n";
                case "rescue.target": return "[Unit]\nDescription=Rescue Mode\nDocumentation=man:systemd.special(7)\nRequires=sysinit.target rescue.service\nAfter=sysinit.target rescue.service\nAllowIsolate=yes\n";
                case "emergency.target": return "[Unit]\nDescription=Emergency Mode\nDocumentation=man:systemd.special(7)\nRequires=emergency.service\nAfter=emergency.service\nAllowIsolate=yes\n";
                case "default.target": return null;
            }
            return null;
        }

        public static string DocText(Pkg p, string path)
        {
            switch (p.Name)
            {
                case "chrony": return path.EndsWith("FAQ", StringComparison.Ordinal) ? "Frequently asked questions about chrony (Cert Lab's short version)\n\n1. How do I use a particular server?\n   Put a 'server NAME iburst' line in /etc/chrony.conf and restart chronyd.\n2. How can I check the time is synchronised?\n   Run 'chronyc sources -v' or 'chronyc tracking'.\n" : "chrony is a versatile implementation of the Network Time Protocol (NTP).\nThe configuration file is /etc/chrony.conf; chronyc is the command-line client.\n";
                case "autofs": return "autofs mounts file systems when they are first used and unmounts them after a while.\nThe master map is /etc/auto.master (and files in /etc/auto.master.d/*.autofs).\nEach line names a mount point and a map file; map lines are: key [-options] location\nA * key with & in the location matches any name (wildcard map).\n";
                case "sudo": return "sudo lets a permitted user run a command as root or another user, as set in /etc/sudoers\n(edit it with visudo) and the files in /etc/sudoers.d.\n";
                case "firewalld": return "firewalld provides a dynamically managed firewall with zones.\nUse firewall-cmd: changes without --permanent last until a reload or reboot;\nwith --permanent they are saved under /etc/firewalld and need firewall-cmd --reload to apply now.\n";
                case "lvm2": return "LVM2: physical volumes (pvcreate) are grouped into volume groups (vgcreate) from which\nlogical volumes are made (lvcreate). lvextend -r also grows the file system.\n";
                case "tuned": return "TuneD applies tuning profiles. tuned-adm list shows them, tuned-adm recommend suggests one,\ntuned-adm profile NAME switches, tuned-adm active shows the current one.\n";
                case "podman": return "Podman runs OCI containers without a daemon. Rootless containers run as the user.\nSee podman(1), podman-run(1) and podman-systemd.unit(5) for Quadlet files.\n";
                case "nfs-utils": return "NFS utilities. Clients mount exports with: mount -t nfs server:/path /mountpoint\nshowmount -e server lists what a server exports.\n";
                case "httpd-core": return "The Apache HTTP Server. The main configuration file is /etc/httpd/conf/httpd.conf;\nextra files go in /etc/httpd/conf.d/*.conf. Web content is served from /var/www/html.\n";
                case "cronie": return "cronie runs scheduled jobs: user crontabs (crontab -e) in /var/spool/cron, system jobs in\n/etc/crontab and /etc/cron.d, and the periodic folders through anacron.\n";
                case "openssh": return "OpenSSH: ssh (client), sshd (server), scp and sftp (file copy), ssh-keygen (keys).\nServer settings: /etc/ssh/sshd_config and /etc/ssh/sshd_config.d/*.conf (the first value found wins).\n";
                case "bash": return "Bash FAQ (Cert Lab's short version)\n\nQ: Where are my settings?  A: ~/.bashrc (interactive shells) and ~/.bash_profile (login shells).\n";
            }
            return p.Summary + "\n";
        }

        static void InitConfigs()
        {
            C("openssh-server", "/etc/ssh/sshd_config", "#\t$OpenBSD: sshd_config,v 1.104 2021/07/02 05:11:21 dtucker Exp $\n\n# This is the sshd server system-wide configuration file.  See\n# sshd_config(5) for more information.\n\n# To modify the system-wide sshd configuration, create a  *.conf  file under\n#  /etc/ssh/sshd_config.d/  which will be automatically included below\nInclude /etc/ssh/sshd_config.d/*.conf\n\n#Port 22\n#AddressFamily any\n#ListenAddress 0.0.0.0\n\n#HostKey /etc/ssh/ssh_host_rsa_key\n#HostKey /etc/ssh/ssh_host_ecdsa_key\n#HostKey /etc/ssh/ssh_host_ed25519_key\n\n# Logging\n#SyslogFacility AUTH\n#LogLevel INFO\n\n# Authentication:\n\n#LoginGraceTime 2m\n#PermitRootLogin prohibit-password\n#StrictModes yes\n#MaxAuthTries 6\n#MaxSessions 10\n\n#PubkeyAuthentication yes\n\n# The default is to check both .ssh/authorized_keys and .ssh/authorized_keys2\n# but this is overridden so installations will only check .ssh/authorized_keys\nAuthorizedKeysFile\t.ssh/authorized_keys\n\n# To disable tunneled clear text passwords, change to no here!\n#PasswordAuthentication yes\n#PermitEmptyPasswords no\n\n#UsePAM no\n\n#X11Forwarding no\n#PrintMotd yes\n#ClientAliveInterval 0\n#UseDNS no\n#Banner none\n\n# override default of no subsystems\nSubsystem\tsftp\t/usr/libexec/openssh/sftp-server\n", 0x180);
            C("openssh-server", "/etc/ssh/sshd_config.d/50-redhat.conf", "# This system is following system-wide crypto policy. The changes to\n# crypto properties (Ciphers, MACs, ...) will not have any effect in\n# this or following included files. To override some configuration option,\n# write it before this block or include it before this file.\n# Please, see manual pages for update-crypto-policies(8) and sshd_config(5).\nInclude /etc/crypto-policies/back-ends/opensshserver.config\n\nSyslogFacility AUTHPRIV\n\nChallengeResponseAuthentication no\n\nGSSAPIAuthentication yes\nGSSAPICleanupCredentials no\n\nUsePAM yes\n\nX11Forwarding yes\n\n# It is recommended to use pam_motd in /etc/pam.d/sshd instead of PrintMotd,\n# as it is more configurable and versatile than the built-in version.\nPrintMotd no\n", 0x180);
            C("openssh-server", "/etc/ssh/sshd_config.d/01-permitrootlogin.conf", "# This file has been generated by the Anaconda Installer.\n# Allow root to log in using ssh. Remove this file to opt-out.\nPermitRootLogin yes\n", 0x180);
            C("openssh-server", "/etc/sysconfig/sshd", "# Configuration file for the sshd service.\n\n# The server keys are automatically generated if they are missing.\n# To change the automatic creation, adjust sshd.service options for\n# example using  systemctl enable sshd-keygen@dsa.service  to allow creation\n# of DSA key or  systemctl mask sshd-keygen@rsa.service  to disable RSA key\n# creation.\n\n# Do not change this option unless you have hardware random\n# generator and you REALLY know what you are doing\n\nSSH_USE_STRONG_RNG=0\n# SSH_USE_STRONG_RNG=1\n\n# System-wide crypto policy:\n# To opt-out, uncomment the following line\n# CRYPTO_POLICY=\n");
            C("openssh-clients", "/etc/ssh/ssh_config", "#\t$OpenBSD: ssh_config,v 1.35 2020/07/17 03:43:42 dtucker Exp $\n\n# This is the ssh client system-wide configuration file.  See\n# ssh_config(5) for more information.  This file provides defaults for\n# users, and the values can be changed in per-user configuration files\n# or on the command line.\n\n# Configuration data is parsed as follows:\n#  1. command line options\n#  2. user-specific file\n#  3. system-wide file\n# Any configuration value is only changed the first time it is set.\n\n# Host *\n#   PasswordAuthentication yes\n#   IdentityFile ~/.ssh/id_rsa\n#   Port 22\n#   StrictHostKeyChecking ask\n\nInclude /etc/ssh/ssh_config.d/*.conf\n");
            C("openssh-clients", "/etc/ssh/ssh_config.d/50-redhat.conf", "# The options here are in the \"Match final block\" to be applied as the last\n# options and could be potentially overwritten by the user configuration\nMatch final all\n\t# Follow system-wide Crypto Policy, if defined:\n\tInclude /etc/crypto-policies/back-ends/openssh.config\n\n\tGSSAPIAuthentication yes\n\n# If this option is set to yes then remote X11 clients will have full access\n# to the original X11 display. As virtually no X11 client supports the untrusted\n# mode correctly we set this to yes.\n\tForwardX11Trusted yes\n\n# Uncomment this if you want to use .local domain\n# Host *.local\n");
            C("chrony", "/etc/chrony.conf", "# Use public servers from the pool.ntp.org project.\n# Please consider joining the pool (https://www.pool.ntp.org/join.html).\npool 2.rhel.pool.ntp.org iburst\n\n# Use NTP servers from DHCP.\nsourcedir /run/chrony-dhcp\n\n# Record the rate at which the system clock gains/losses time.\ndriftfile /var/lib/chrony/drift\n\n# Allow the system clock to be stepped in the first three updates\n# if its offset is larger than 1 second.\nmakestep 1.0 3\n\n# Enable kernel synchronization of the real-time clock (RTC).\nrtcsync\n\n# Enable hardware timestamping on all interfaces that support it.\n#hwtimestamp *\n\n# Increase the minimum number of selectable sources required to adjust\n# the system clock.\n#minsources 2\n\n# Allow NTP client access from local network.\n#allow 192.168.0.0/16\n\n# Serve time even if not synchronized to a time source.\n#local stratum 10\n\n# Require authentication (nts or key option) for all NTP sources.\n#authselectmode require\n\n# Specify file containing keys for NTP authentication.\nkeyfile /etc/chrony.keys\n\n# Save NTS keys and cookies.\nntsdumpdir /var/lib/chrony\n\n# Insert/delete leap seconds by slewing instead of stepping.\n#leapsecmode slew\n\n# Get TAI-UTC offset and leap seconds from the system tz database.\nleapsectz right/UTC\n\n# Specify directory for log files.\nlogdir /var/log/chrony\n\n# Select which information is logged.\n#log measurements statistics tracking\n");
            C("chrony", "/etc/chrony.keys", "# This is an example chrony keys file.\n", 0x1A0);
            C("firewalld", "/etc/firewalld/firewalld.conf", "# firewalld config file\n\n# default zone\n# The default zone used if an empty zone string is used.\n# Default: public\nDefaultZone=public\n\n# Clean up on exit\n# If set to no or false the firewall configuration will not get cleaned up\n# on exit or stop of firewalld.\n# Default: yes\nCleanupOnExit=yes\n\n# Lockdown\n# If set to enabled, firewall changes with the D-Bus interface will be limited\n# to applications that are listed in the lockdown whitelist.\n# Default: no\nLockdown=no\n\n# IPv6_rpfilter\n# Performs a reverse path filter test on a packet for IPv6.\nIPv6_rpfilter=yes\n\n# FirewallBackend\n# Selects the firewall backend implementation.\n# Default: nftables\nFirewallBackend=nftables\n", 0x180);
            C("firewalld", "/etc/firewalld/zones/", "", 0x1E8);
            C("firewalld", "/etc/firewalld/services/", "", 0x1E8);
            C("rsyslog", "/etc/rsyslog.conf", "# rsyslog configuration file\n\n# For more information see /usr/share/doc/rsyslog-*/rsyslog_conf.html\n# or latest version online at http://www.rsyslog.com/doc/rsyslog_conf.html\n# If you experience problems, see http://www.rsyslog.com/doc/troubleshoot.html\n\n#### GLOBAL DIRECTIVES ####\n\n# Where to place auxiliary files\nglobal(workDirectory=\"/var/lib/rsyslog\")\n\n# Use default timestamp format\nmodule(load=\"builtin:omfile\" Template=\"RSYSLOG_TraditionalFileFormat\")\n\n#### MODULES ####\n\nmodule(load=\"imuxsock\"    # provides support for local system logging (e.g. via logger command)\n       SysSock.Use=\"off\") # Turn off message reception via local log socket;\n                          # local messages are retrieved through imjournal now.\nmodule(load=\"imjournal\"             # provides access to the systemd journal\n       StateFile=\"imjournal.state\") # File to store the position in the journal\n#module(load=\"imklog\") # reads kernel messages (the same are read from journald)\n#module(load=\"immark\") # provides --MARK-- message capability\n\n# Include all config files in /etc/rsyslog.d/\ninclude(file=\"/etc/rsyslog.d/*.conf\" mode=\"optional\")\n\n# Provides UDP syslog reception\n# for parameters see http://www.rsyslog.com/doc/imudp.html\n#module(load=\"imudp\") # needs to be done just once\n#input(type=\"imudp\" port=\"514\")\n\n# Provides TCP syslog reception\n# for parameters see http://www.rsyslog.com/doc/imtcp.html\n#module(load=\"imtcp\") # needs to be done just once\n#input(type=\"imtcp\" port=\"514\")\n\n#### RULES ####\n\n# Log all kernel messages to the console.\n# Logging much else clutters up the screen.\n#kern.*                                                 /dev/console\n\n# Log anything (except mail) of level info or higher.\n# Don't log private authentication messages!\n*.info;mail.none;authpriv.none;cron.none                /var/log/messages\n\n# The authpriv file has restricted access.\nauthpriv.*                                              /var/log/secure\n\n# Log all the mail messages in one place.\nmail.*                                                  -/var/log/maillog\n\n\n# Log cron stuff\ncron.*                                                  /var/log/cron\n\n# Everybody gets emergency messages\n*.emerg                                                 :omusrmsg:*\n\n# Save news errors of level crit and higher in a special file.\nuucp,news.crit                                          /var/log/spooler\n\n# Save boot messages also to boot.log\nlocal7.*                                                /var/log/boot.log\n");
            C("rsyslog", "/etc/rsyslog.d/", "", 0x1ED);
            C("cronie", "/etc/crontab", "SHELL=/bin/bash\nPATH=/sbin:/bin:/usr/sbin:/usr/bin\nMAILTO=root\n\n# For details see man 4 crontabs\n\n# Example of job definition:\n# .---------------- minute (0 - 59)\n# |  .------------- hour (0 - 23)\n# |  |  .---------- day of month (1 - 31)\n# |  |  |  .------- month (1 - 12) OR jan,feb,mar,apr ...\n# |  |  |  |  .---- day of week (0 - 6) (Sunday=0 or 7) OR sun,mon,tue,wed,thu,fri,sat\n# |  |  |  |  |\n# *  *  *  *  * user-name  command to be executed\n\n");
            C("cronie", "/etc/cron.d/0hourly", "# Run the hourly jobs\nSHELL=/bin/bash\nPATH=/sbin:/bin:/usr/sbin:/usr/bin\nMAILTO=root\n01 * * * * root run-parts /etc/cron.hourly\n");
            C("cronie", "/etc/cron.deny", "");
            C("cronie", "/etc/anacrontab", "# /etc/anacrontab: configuration file for anacron\n\n# See anacron(8) and anacrontab(5) for details.\n\nSHELL=/bin/sh\nPATH=/sbin:/bin:/usr/sbin:/usr/bin\nMAILTO=root\n# the maximal random delay added to the base delay of the jobs\nRANDOM_DELAY=45\n# the jobs will be started during the following hours only\nSTART_HOURS_RANGE=3-22\n\n#period in days   delay in minutes   job-identifier   command\n1\t5\tcron.daily\t\tnice run-parts /etc/cron.daily\n7\t25\tcron.weekly\t\tnice run-parts /etc/cron.weekly\n@monthly 45\tcron.monthly\t\tnice run-parts /etc/cron.monthly\n");
            C("cronie", "/etc/sysconfig/crond", "# Settings for the CRON daemon.\n# CRONDARGS= :  any extra command-line startup arguments for crond\nCRONDARGS=\n");
            foreach (var d in new[] { "/etc/cron.hourly/", "/etc/cron.daily/", "/etc/cron.weekly/", "/etc/cron.monthly/", "/var/spool/cron/" }) C("cronie", d, "", d.StartsWith("/var", StringComparison.Ordinal) ? 0x1C0 : 0x1ED);
            C("at", "/etc/at.deny", "");
