        const string SudoersText = "## Sudoers allows particular users to run various commands as\n## the root user, without needing the root password.\n##\n## Examples are provided at the bottom of the file for collections\n## of related commands, which can then be delegated out to particular\n## users or groups.\n##\n## This file must be edited with the 'visudo' command.\n\n## Host Aliases\n## Groups of machines. You may prefer to use hostnames (perhaps using\n## wildcards for entire domains) or IP addresses instead.\n# Host_Alias     FILESERVERS = fs1, fs2\n# Host_Alias     MAILSERVERS = smtp, smtp2\n\n## User Aliases\n## These aren't often necessary, as you can use regular groups\n## (ie, from files, LDAP, NIS, etc) in this file - just use %groupname\n## rather than USERALIAS\n# User_Alias ADMINS = jsmith, mikem\n\n## Command Aliases\n## These are groups of related commands...\n\n## Networking\n# Cmnd_Alias NETWORKING = /sbin/route, /sbin/ifconfig, /bin/ping, /sbin/dhclient, /usr/bin/net, /sbin/iptables, /usr/bin/rfcomm, /usr/bin/wvdial, /sbin/iwconfig, /sbin/mii-tool\n\n## Software\n# Cmnd_Alias SOFTWARE = /bin/rpm, /usr/bin/up2date, /usr/bin/yum\n\n## Services\n# Cmnd_Alias SERVICES = /sbin/service, /sbin/chkconfig, /usr/bin/systemctl start, /usr/bin/systemctl stop, /usr/bin/systemctl reload, /usr/bin/systemctl restart, /usr/bin/systemctl status, /usr/bin/systemctl enable, /usr/bin/systemctl disable\n\n## Defaults specification\n\n#\n# Refuse to run if unable to disable echo on the tty.\n#\nDefaults   !visiblepw\n\nDefaults    always_set_home\nDefaults    match_group_by_gid\n\n# Prior to version 1.8.15, groups listed in sudoers that were not\n# found in the system group database were passed to the group\n# plugin, if any. Starting with 1.8.15, only groups of the form\n# %:group are resolved via the group plugin by default.\n# We enable always_query_group_plugin to restore old behavior.\n# Disable this option for new behavior.\nDefaults    always_query_group_plugin\n\nDefaults    env_reset\nDefaults    env_keep =  \"COLORS DISPLAY HOSTNAME HISTSIZE KDEDIR LS_COLORS\"\nDefaults    env_keep += \"MAIL QTDIR USERNAME LANG LC_ADDRESS LC_CTYPE\"\n\nDefaults    secure_path = /sbin:/bin:/usr/sbin:/usr/bin\n\n## Next comes the main part: which users can run what software on\n## which machines (the sudoers file can be shared between multiple\n## systems).\n## Syntax:\n##\n##      user    MACHINE=COMMANDS\n##\n## The COMMANDS section may have other options added to it.\n##\n## Allow root to run any commands anywhere\nroot    ALL=(ALL)       ALL\n\n## Allows members of the 'sys' group to run networking, software,\n## service management apps and more.\n# %sys ALL = NETWORKING, SOFTWARE, SERVICES, STORAGE, DELEGATING, PROCESSES, LOCATE, DRIVERS\n\n## Allows people in group wheel to run all commands\n%wheel  ALL=(ALL)       ALL\n\n## Same thing without a password\n# %wheel        ALL=(ALL)       NOPASSWD: ALL\n\n## Allows members of the users group to mount and unmount the\n## cdrom as root\n# %users  ALL=/sbin/mount /mnt/cdrom, /sbin/umount /mnt/cdrom\n\n## Allows members of the users group to shutdown this system\n# %users  localhost=/sbin/shutdown -h now\n\n## Read drop-in files from /etc/sudoers.d (the # here does not mean a comment)\n#includedir /etc/sudoers.d\n";

        const string LoginDefs = "#\n# Please note that the parameters in this configuration file control the\n# behavior of the tools from the shadow-utils component. None of these\n# tools uses the PAM mechanism, and the utilities that use PAM (such as the\n# passwd command) should therefore be configured elsewhere. Refer to\n# /etc/pam.d/system-auth for more information.\n#\n\n#\n# Delay in seconds before being allowed another attempt after a login failure\n# Note: When PAM is used, some modules may enforce a minimum delay (e.g.\n#       pam_unix(8) enforces a 2s delay)\n#\n#FAIL_DELAY\t\t3\n\n# Currently FAILLOG_ENAB is not supported\n\n#\n# Enable display of unknown usernames when login(1) failures are recorded.\n#\n#LOG_UNKFAIL_ENAB\tno\n\n# Currently LOG_OK_LOGINS is not supported\n\n# Currently LASTLOG_ENAB is not supported\n\n#\n# Limit the use of su(1).\n#\n#SULOG_FILE\n\n#\n# *REQUIRED*\n#   Directory where mailboxes reside, _or_ name of file, relative to the\n#   home directory.  If you _do_ define both, MAIL_DIR takes precedence.\n#\nMAIL_DIR\t/var/spool/mail\n#MAIL_FILE\t.mail\n\n# Password aging controls:\n#\n#\tPASS_MAX_DAYS\tMaximum number of days a password may be used.\n#\tPASS_MIN_DAYS\tMinimum number of days allowed between password changes.\n#\tPASS_MIN_LEN\tMinimum acceptable password length.\n#\tPASS_WARN_AGE\tNumber of days warning given before a password expires.\n#\nPASS_MAX_DAYS\t99999\nPASS_MIN_DAYS\t0\nPASS_WARN_AGE\t7\n\n#\n# Min/max values for automatic uid selection in useradd(8)\n#\nUID_MIN                  1000\nUID_MAX                 60000\n# System accounts\nSYS_UID_MIN               201\nSYS_UID_MAX               999\n# Extra per user uids\nSUB_UID_MIN                100000\nSUB_UID_MAX             600100000\nSUB_UID_COUNT               65536\n\n#\n# Min/max values for automatic gid selection in groupadd(8)\n#\nGID_MIN                  1000\nGID_MAX                 60000\n# System accounts\nSYS_GID_MIN               201\nSYS_GID_MAX               999\n# Extra per user group ids\nSUB_GID_MIN                100000\nSUB_GID_MAX             600100000\nSUB_GID_COUNT               65536\n\n#\n# If useradd(8) should create home directories for users by default (non\n# system users only).\n# This option is overridden with the -M or -m flags on the useradd(8)\n# command-line.\n#\nCREATE_HOME     yes\n\n#\n# Permission mask is initialized to this value. If not specified,\n# the permission mask will be initialized to 022.\nUMASK           022\n\n#\n# HOME_MODE is used by useradd(8) and newusers(8) to set the mode for new\n# home directories.\n# If HOME_MODE is not set, the value of UMASK is used to create the mode.\nHOME_MODE       0700\n\n# This enables userdel to remove user groups if no members exist.\n#\nUSERGROUPS_ENAB yes\n\n# If defined, this command is run when removing a user.\n# It should remove any at/cron/print jobs etc. owned by\n# the user to be removed (passed as the first argument).\n#\n#USERDEL_CMD\t/usr/sbin/userdel_local\n\n#\n# If set to MD5, MD5-based algorithm will be used for encrypting password\n# If set to SHA256, SHA256-based algorithm will be used for encrypting password\n# If set to SHA512, SHA512-based algorithm will be used for encrypting password\n# If set to BLOWFISH, BLOWFISH-based algorithm will be used for encrypting password\n# If set to DES, DES-based algorithm will be used for encrypting password (default)\n#\nENCRYPT_METHOD SHA512\n";

        const string HttpdConf = "#\n# This is the main Apache HTTP server configuration file.  It contains the\n# configuration directives that give the server its instructions.\n# See <URL:http://httpd.apache.org/docs/2.4/> for detailed information.\n# In particular, see\n# <URL:http://httpd.apache.org/docs/2.4/mod/directives.html>\n# for a discussion of each configuration directive.\n#\n# ServerRoot: The top of the directory tree under which the server's\n# configuration, error, and log files are kept.\n#\nServerRoot \"/etc/httpd\"\n\n#\n# Listen: Allows you to bind Apache to specific IP addresses and/or\n# ports, instead of the default. See also the <VirtualHost>\n# directive.\n#\n#Listen 12.34.56.78:80\nListen 80\n\n#\n# Dynamic Shared Object (DSO) Support\n#\nInclude conf.modules.d/*.conf\n\n#\n# If you wish httpd to run as a different user or group, you must run\n# httpd as root initially and it will switch.\n#\nUser apache\nGroup apache\n\n# 'Main' server configuration\n#\nServerAdmin root@localhost\n\n#\n# ServerName gives the name and port that the server uses to identify itself.\n#\n#ServerName www.example.com:80\n\n#\n# Deny access to the entirety of your server's filesystem. You must\n# explicitly permit access to web content directories in other\n# <Directory> blocks below.\n#\n<Directory />\n    AllowOverride none\n    Require all denied\n</Directory>\n\n#\n# DocumentRoot: The directory out of which you will serve your\n# documents. By default, all requests are taken from this directory, but\n# symbolic links and aliases may be used to point to other locations.\n#\nDocumentRoot \"/var/www/html\"\n\n#\n# Relax access to content within /var/www.\n#\n<Directory \"/var/www\">\n    AllowOverride None\n    # Allow open access:\n    Require all granted\n</Directory>\n\n# Further relax access to the default document root:\n<Directory \"/var/www/html\">\n    Options Indexes FollowSymLinks\n    AllowOverride None\n    Require all granted\n</Directory>\n\n#\n# DirectoryIndex: sets the file that Apache will serve if a directory\n# is requested.\n#\n<IfModule dir_module>\n    DirectoryIndex index.html\n</IfModule>\n\n#\n# The following lines prevent .htaccess and .htpasswd files from being\n# viewed by Web clients.\n#\n<Files \".ht*\">\n    Require all denied\n</Files>\n\nErrorLog \"logs/error_log\"\n\nLogLevel warn\n\n<IfModule log_config_module>\n    LogFormat \"%h %l %u %t \\\"%r\\\" %>s %b \\\"%{Referer}i\\\" \\\"%{User-Agent}i\\\"\" combined\n    CustomLog \"logs/access_log\" combined\n</IfModule>\n\nAddDefaultCharset UTF-8\n\nEnableSendfile on\n\n# Supplemental configuration\n#\n# Load config files in the \"/etc/httpd/conf.d\" directory, if any.\nIncludeOptional conf.d/*.conf\n";

        /// <summary>What installing a package does besides its files: system users, folders.</summary>
        public static void AfterInstall(Machine m, Pkg p)
        {
            switch (p.Name)
            {
                case "httpd-filesystem": case "httpd": m.AddSystemUser("apache", 48, 48, "Apache", "/usr/share/httpd", "/sbin/nologin"); break;
                case "nginx": m.AddSystemUser("nginx", 994, 994, "Nginx web server", "/var/lib/nginx", "/sbin/nologin"); break;
                case "mariadb-server": m.AddSystemUser("mysql", 27, 27, "MariaDB Server", "/var/lib/mysql", "/sbin/nologin"); break;
                case "cockpit-ws": m.AddSystemUser("cockpit-ws", 993, 993, "User for cockpit web service", "/nonexisting", "/sbin/nologin"); break;
                case "setroubleshoot-server": m.AddSystemUser("setroubleshoot", 992, 992, "SELinux troubleshoot server", "/var/lib/setroubleshoot", "/sbin/nologin"); break;
            }
            if (p.Name == "httpd")
            {
                foreach (var d in new[] { "/var/www/html", "/var/www/cgi-bin" }) { var n = m.V.EnsureDir(d, 0x1ED, null); }
                m.V.EnsureDir("/var/log/httpd", 0x1C0, null);
                m.V.EnsureDir("/etc/httpd/logs", 0x1ED, null);
            }
        }
    }
}
